Tool response:
Tool: create_change_order
Description: Create Change Order
Parameters:
    {
      "type": "object",
      "properties": {
        "project_id": {
          "type": "string",
          "title": "Project Id"
        },
        "title": {
          "type": "string",
          "title": "Title"
        },
        "scope_description": {
          "type": "string",
          "title": "Scope Description"
        },
        "cost_impact": {
          "type": "number",
          "title": "Cost Impact"
        },
        "cost_code_id": {
          "type": "integer",
          "title": "Cost Code Id"
        },
        "schedule_impact_days": {
          "type": "integer",
          "title": "Schedule Impact Days"
        },
        "schedule_impact_phase_id": {
          "type": "integer",
          "title": "Schedule Impact Phase Id"
        }
      },
      "required": [
        "project_id",
        "title",
        "scope_description",
        "cost_impact",
        "cost_code_id",
        "schedule_impact_days",
        "schedule_impact_phase_id"
      ]
    }

Tool response:
Tool: find_cost_code_by_code
Description: Find Cost Code By Code
Parameters:
    {
      "type": "object",
      "properties": {
        "code": {
          "type": "string",
          "description": "The cost code identifier (e.g., '08 81 00')",
          "title": "Code"
        }
      },
      "required": [
        "code"
      ]
    }

Tool response:
Tool: find_phase_by_project_and_name
Description: Find Phase By Project And Name
Parameters:
    {
      "type": "object",
      "properties": {
        "project_id": {
          "type": "string",
          "description": "Unique identifier of the project",
          "title": "Project Id"
        },
        "name": {
          "type": "string",
          "description": "Name of the project phase (e.g., 'Roofing')",
          "title": "Name"
        }
      },
      "required": [
        "project_id",
        "name"
      ]
    }

Tool response:
Tool: upload_attachment
Description: Upload Attachment
Parameters:
    {
      "type": "object",
      "properties": {
        "change_order_id": {
          "type": "integer",
          "description": "ID of the change order to which the attachment belongs",
          "title": "Change Order Id"
        },
        "file_name": {
          "type": "string",
          "title": "File Name"
        },
        "file_type": {
          "type": "string",
          "title": "File Type"
        },
        "file_size_bytes": {
          "type": "integer",
          "title": "File Size Bytes"
        },
        "file_content": {
          "type": "string",
          "title": "File Content"
        },
        "description": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Description"
        }
      },
      "required": [
        "change_order_id",
        "file_name",
        "file_type",
        "file_size_bytes",
        "file_content"
      ]
    }
